from pathlib import Path
import base64, hashlib, json, lzma
marker = Path('.staging/applied-02')
if marker.exists():
    raise SystemExit(0)
data = ''''''
raw = base64.b64decode(data)
assert hashlib.sha256(raw).hexdigest() == 'ac12731e3e20f5632a4f7eb3ce8441394e9f2618eea3a2b96b0f3073b1862dfe'
payload = json.loads(lzma.decompress(raw))
Path('apps/runner/src/agent/workspaces.ts').write_text(payload['work'])
p = Path('tests/runner-agent.test.ts'); s = p.read_text()
assert s.count('  symlink,\n') == 1 and "test('Git clean/process" not in s
p.write_text(s.replace('  symlink,\n', '  symlink,\n  utimes,\n') + '\n' + payload['newtests'])
for path, old, new in payload['changes']:
    p=Path(path);s=p.read_text();assert s.count(old)==1,(path,old);p.write_text(s.replace(old,new))
for path in ['docs/engineering/runner-node.md', 'docs/engineering/adr-0006-node-metadata.md']:
    p=Path(path);p.write_text(p.read_text()+'\n## Git 配置隔离补充\n\n'+payload['extra']+'\n')
p=Path('docs/development/21-implementation-status.md');p.write_text(p.read_text().replace('116','119'))
marker.write_text('Isolated metadata config, filter/race regression tests and browser navigation fixes applied.\n')
